void slidingMax(int a[], int n, int k, int res[]) {
    int dq[n], fr=0, re=0;
    for (int i=0; i<n; i++) {
        while (fr<re&&dq[fr]<i-k+1)fr++;
        while (fr<re&&a[dq[re-1]]<=a[i])re--;
        dq[re++]=i;
        if (i>=k-1)res[i-k+1]=a[dq[fr]];
    }
}

